const prisma = require("./lib/prisma");

// Helper function to add a file
const addFile = async (fileData) => {
  try {
    const newFile = await prisma.uploaded_file.create({
      data: {
        // id is auto-generated by Prisma (@default(uuid()))
        ...fileData,
        size: parseInt(fileData.size, 10), // Ensure size is an integer
      },
    });
    return newFile;
  } catch (error) {
    console.error("Prisma error adding file:", error);
    return null;
  }
};

// Helper function to get all files
const getFiles = async () => {
  try {
    const files = await prisma.uploaded_file.findMany({
      orderBy: {
        uploadDate: "desc",
      },
      // Select only the fields needed for the list view
      select: {
        id: true,
        title: true,
        originalname: true,
        size: true,
        uploadDate: true,
        fileType: true,
        extractedText: true, // Needed for search index initialization
      },
    });
    return files;
  } catch (error) {
    console.error("Prisma error getting files:", error);
    return [];
  }
};

// Helper function to search files (NOW USES FLEXSEARCH)
const getFilesByIds = async (ids) => {
  if (!ids || ids.length === 0 || (ids.length === 1 && ids[0] === undefined)) {
    return [];
  }
  
  try {
    const files = await prisma.uploaded_file.findMany({
      where: {
        id: {
          in: ids,
        },
      },
      select: {
        id: true,
        title: true,
        originalname: true,
        size: true,
        uploadDate: true,
        fileType: true,
        extractedText: true, // For the snippet
      },
    });
    return files;
  } catch (error) {
    console.error("Prisma error searching files:", error);
    return [];
  }
};

const getFileById = async (id) => {
  try {
    const file = await prisma.uploaded_file.findUnique({
      where: { id: id },
    });
    return file;
  } catch (error) {
    console.error("Prisma error getting file by ID:", error);
    return null;
  }
};

const deleteFile = async (id) => {
  try {
    await prisma.uploaded_file.delete({
      where: { id: id },
    });
    return true;
  } catch (error) {
    console.error("Prisma error deleting file:", error);
    return false;
  }
};

module.exports = {
  addFile,
  getFiles,
  getFilesByIds,
  getFileById,
  deleteFile,
};
